import React, { useState } from "react";

/* 3.x — The harness. Switch the five parts off one at a time and watch what
   the agent starts getting away with.

   The argument this has to make visually is the one every article makes in
   prose: the model is the small thing in the middle, and a newer model moves
   the number far less than the scaffolding around it does. So the model here
   is a toggle too — and upgrading it on a bare loop is visibly worse than
   keeping the old model and building the harness. */

const PARTS = [
  {
    id: "context",
    label: "context",
    weight: 16,
    is: "Assemble exactly what this step needs — the conventions file, the relevant code, the decision made two turns ago.",
    without:
      "It re-reads everything every turn, fills the window with noise, and forgets the decision it made two steps ago.",
  },
  {
    id: "tools",
    label: "tools",
    weight: 14,
    is: "Schemas, validation, timeouts, and a real error when something fails.",
    without:
      "A tool times out, the loop treats the error string as a result, and plans its next move on top of it.",
  },
  {
    id: "verify",
    label: "verify",
    weight: 28,
    is: "Something that re-runs the work before the result counts — tests, a type check, a second model reading the diff.",
    without:
      "Nothing re-runs anything, so “done” means the model said done. A loop without sensors produces hallucinated completion at high speed.",
  },
  {
    id: "budget",
    label: "budget",
    weight: 6,
    is: "A ceiling per task — tokens, calls, wall-clock — that kills the run rather than asking nicely.",
    without: "One malformed plan retries forever. You find out from the invoice.",
  },
  {
    id: "trace",
    label: "trace",
    weight: 14,
    is: "Every step recorded: what went in, which tool ran, what came back. Then evals over those traces.",
    without:
      "It failed on Tuesday and there is no trace. You cannot say which step went wrong — only rerun it and hope.",
  },
];

const BARE = 6;
const MODEL_GAIN = 12;

export default function Harness() {
  const [off, setOff] = useState(() => new Set());
  const [upgraded, setUpgraded] = useState(false);
  const [focus, setFocus] = useState(null);

  const toggle = (id) =>
    setOff((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  const harness = PARTS.reduce(
    (sum, p) => sum + (off.has(p.id) ? 0 : p.weight),
    0
  );
  const score = BARE + harness + (upgraded ? MODEL_GAIN : 0);
  const shown = focus ? PARTS.find((p) => p.id === focus) : null;
  const broken = PARTS.filter((p) => off.has(p.id));

  /* Blocks left to right; the model sits in the middle of them on purpose. */
  const order = ["context", "tools", "MODEL", "verify", "budget"];
  const slot = (i) => 8 + i * 17.6;

  return (
    <div className="viz hrn">
      <svg
        className="hrn-map"
        viewBox="0 0 100 52"
        role="img"
        aria-label="An agent harness: context, tools, model, verification, budget, and a trace underneath"
      >
        <line className="hrn-wire" x1="2" y1="16" x2="98" y2="16" />

        {order.map((id, i) => {
          if (id === "MODEL") {
            return (
              <g
                key="model"
                className={`hrn-model ${upgraded ? "up" : ""}`}
                onClick={() => setUpgraded((v) => !v)}
              >
                <circle cx={slot(i) + 7} cy="16" r="8.4" />
                <text x={slot(i) + 7} y="17.6">
                  model
                </text>
              </g>
            );
          }
          const part = PARTS.find((p) => p.id === id);
          const dead = off.has(part.id);
          return (
            <g
              key={part.id}
              className={`hrn-part ${dead ? "off" : ""} ${
                focus === part.id ? "on" : ""
              }`}
              onClick={() => toggle(part.id)}
              onMouseEnter={() => setFocus(part.id)}
              onMouseLeave={() => setFocus(null)}
            >
              <rect x={slot(i)} y="8" width="14" height="16" rx="3" />
              <text x={slot(i) + 7} y="17.6">
                {part.label}
              </text>
            </g>
          );
        })}

        {/* The trace runs under all of it, which is where it belongs. */}
        <g
          className={`hrn-part hrn-band ${off.has("trace") ? "off" : ""} ${
            focus === "trace" ? "on" : ""
          }`}
          onClick={() => toggle("trace")}
          onMouseEnter={() => setFocus("trace")}
          onMouseLeave={() => setFocus(null)}
        >
          <rect x="8" y="30" width="83" height="10" rx="3" />
          <text x="49.5" y="37">
            trace · evals
          </text>
        </g>
      </svg>

      {/* One number, and it is the honest one: does the task come out right. */}
      <div className="hrn-meter">
        <span className="hrn-bar">
          <i style={{ transform: `scaleX(${score / 100})` }} />
        </span>
        <b>{score}%</b>
        <em>of tasks come out correct</em>
      </div>

      <div className="viz-presets hrn-keys">
        {PARTS.map((p) => (
          <button
            key={p.id}
            type="button"
            className={`viz-chip ${off.has(p.id) ? "" : "on"}`}
            onClick={() => toggle(p.id)}
            onMouseEnter={() => setFocus(p.id)}
            onMouseLeave={() => setFocus(null)}
          >
            {off.has(p.id) ? "＋" : "−"} {p.label}
          </button>
        ))}
        <button
          type="button"
          className={`viz-chip ${upgraded ? "on" : ""}`}
          onClick={() => setUpgraded((v) => !v)}
        >
          {upgraded ? "newer model ✓" : "swap the model"}
        </button>
      </div>

      <p className="viz-note" aria-live="polite">
        {shown ? (
          <>
            <strong>{shown.label}.</strong>{" "}
            {off.has(shown.id) ? shown.without : shown.is}
          </>
        ) : broken.length ? (
          <>
            <strong>{broken.length} missing.</strong> {broken[0].without}
          </>
        ) : upgraded ? (
          <>
            <strong>The newer model bought you {MODEL_GAIN} points.</strong> The
            harness around it is worth {harness}. That ratio is the entire
            argument — the model is the one part of this diagram you buy.
          </>
        ) : (
          <>
            <strong>Everything except the circle is yours.</strong> Switch a
            block off and see what the agent starts getting away with. Then
            swap the model and watch how little that moves.
          </>
        )}
      </p>

      <p className="viz-caveat">
        The numbers are illustrative, not measured — the weights follow the
        reading below, where verification is repeatedly the single biggest
        lever and a model swap is worth ten to fifteen points. The shape of the
        claim is the point, not the arithmetic.
      </p>
    </div>
  );
}
