import React, { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { tracks } from "./learnData";
import "./ProofMap.css";

/* ============================================================
   THE RECEIPTS
   ------------------------------------------------------------
   The hero promises "with the proof attached", and until now the
   proof lived inside `applied` on each stage — behind a chosen
   path, a clicked track and an opened row. Three clicks deep is
   the same as not there, especially for someone skimming the
   page to decide whether the author has shipped anything.

   This draws every stage → system link at once: stages on the
   left, the production systems on the right, one curve per
   link. Hover either side and only its links stay lit. When
   nobody is touching it, it walks through the systems on its
   own so the idea lands without an interaction.

   Systems are keyed by href, not label — the same project is
   described differently from each stage that points at it.
   ============================================================ */

function systemName(label) {
  return label.split(" — ")[0].trim();
}

function buildGraph() {
  const stages = [];
  const systems = new Map();

  tracks.forEach((t) =>
    t.stages.forEach((st) => {
      if (!st.applied || !st.applied.length) return;
      stages.push({
        id: st.id,
        title: st.title.split(" — ")[0],
        trackId: t.id,
        trackTitle: t.title,
        chip: t.chip,
        accent: t.accent,
        sys: st.applied.map((a) => a.href),
      });
      st.applied.forEach((a) => {
        const s = systems.get(a.href) || {
          href: a.href,
          name: systemName(a.label),
          stages: [],
        };
        if (!s.stages.includes(st.id)) s.stages.push(st.id);
        systems.set(a.href, s);
      });
    })
  );

  const sysList = [...systems.values()].sort(
    (a, b) => b.stages.length - a.stages.length
  );
  const links = [];
  stages.forEach((st) =>
    st.sys.forEach((href) =>
      links.push({ key: `${st.id}>${href}`, stage: st.id, sys: href, accent: st.accent })
    )
  );
  return { stages, systems: sysList, links };
}

const TOUR_MS = 2600;

export default function ProofMap({ onOpenStage, onOpenSystem }) {
  const graph = useMemo(buildGraph, []);
  const wrap = useRef(null);
  const stageEls = useRef({});
  const sysEls = useRef({});
  const [paths, setPaths] = useState([]);
  const [box, setBox] = useState({ w: 0, h: 0 });

  // What is lit. `hover` is a person; `tour` is the page doing it by itself
  // while nobody is. A person always wins.
  const [hover, setHover] = useState(null);
  const [tour, setTour] = useState(0);
  const [inView, setInView] = useState(false);
  const reduced = useRef(
    typeof window !== "undefined" &&
      window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches
  );

  /* ---- geometry: measured, because the lists wrap differently at every
     width and the curves have to meet the actual text. */
  useLayoutEffect(() => {
    const root = wrap.current;
    if (!root) return undefined;

    const measure = () => {
      const r = root.getBoundingClientRect();
      if (!r.width) return;
      const out = [];
      graph.links.forEach((l) => {
        const a = stageEls.current[l.stage];
        const b = sysEls.current[l.sys];
        if (!a || !b) return;
        const ra = a.getBoundingClientRect();
        const rb = b.getBoundingClientRect();
        const x1 = ra.right - r.left + 10;
        const y1 = ra.top + ra.height / 2 - r.top;
        const x2 = rb.left - r.left - 10;
        const y2 = rb.top + rb.height / 2 - r.top;
        const mx = (x1 + x2) / 2;
        out.push({
          ...l,
          d: `M${x1},${y1} C${mx},${y1} ${mx},${y2} ${x2},${y2}`,
        });
      });
      setBox({ w: r.width, h: r.height });
      setPaths(out);
    };

    measure();
    let ro;
    if (typeof ResizeObserver !== "undefined") {
      ro = new ResizeObserver(measure);
      ro.observe(root);
    }
    // Fonts swapping in move every label a few pixels.
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(measure);
    return () => ro && ro.disconnect();
  }, [graph]);

  useEffect(() => {
    const el = wrap.current;
    if (!el || typeof IntersectionObserver === "undefined") return undefined;
    const io = new IntersectionObserver(([e]) => setInView(e.isIntersecting), {
      threshold: 0.25,
    });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  useEffect(() => {
    if (hover || !inView || reduced.current) return undefined;
    const id = setInterval(
      () => setTour((n) => (n + 1) % graph.systems.length),
      TOUR_MS
    );
    return () => clearInterval(id);
  }, [hover, inView, graph.systems.length]);

  const active =
    hover ||
    (inView && !reduced.current && graph.systems[tour]
      ? { kind: "sys", id: graph.systems[tour].href, auto: true }
      : null);

  const litStage = (id) => {
    if (!active) return false;
    if (active.kind === "stage") return active.id === id;
    return graph.links.some((l) => l.sys === active.id && l.stage === id);
  };
  const litSys = (href) => {
    if (!active) return false;
    if (active.kind === "sys") return active.id === href;
    return graph.links.some((l) => l.stage === active.id && l.sys === href);
  };
  const litLink = (l) =>
    active &&
    (active.kind === "sys" ? l.sys === active.id : l.stage === active.id);

  const trackCount = new Set(graph.stages.map((s) => s.trackId)).size;

  return (
    <section className="lrn-proof" id="proof" data-reveal>
      <div className="lrn-proof-head">
        <p className="lrn-eyebrow">The receipts</p>
        <h2 className="lrn-h2">
          Every stage points at something I <em>shipped</em>
        </h2>
        <p className="lrn-lede">
          {graph.stages.length} stages across {trackCount} tracks feed{" "}
          {graph.systems.length} systems that are running, or ran, in front of
          real users. Hover a system to see what it was built from; click
          either side to go there.
        </p>
      </div>

      <div
        className={`lrn-proof-map${active ? " has-active" : ""}`}
        ref={wrap}
        onMouseLeave={() => setHover(null)}
      >
        <svg
          className="lrn-proof-links"
          width={box.w}
          height={box.h}
          viewBox={`0 0 ${box.w || 1} ${box.h || 1}`}
          aria-hidden="true"
        >
          {paths.map((p) => (
            <path
              key={p.key}
              d={p.d}
              className={litLink(p) ? "on" : undefined}
              style={{ "--c": p.accent }}
            />
          ))}
        </svg>

        <ol className="lrn-proof-stages" aria-label="Stages">
          {graph.stages.map((st) => (
            <li key={st.id}>
              <button
                type="button"
                ref={(el) => {
                  stageEls.current[st.id] = el;
                }}
                className={`lrn-proof-stage${litStage(st.id) ? " on" : ""}`}
                style={{ "--c": st.accent }}
                onMouseEnter={() => setHover({ kind: "stage", id: st.id })}
                onFocus={() => setHover({ kind: "stage", id: st.id })}
                onBlur={() => setHover(null)}
                onClick={() => onOpenStage(st.id, st.trackId)}
                title={`${st.trackTitle} — open this stage`}
              >
                <i aria-hidden="true" />
                <span className="lrn-proof-chip">{st.chip}</span>
                {st.title}
              </button>
            </li>
          ))}
        </ol>

        <ul className="lrn-proof-systems" aria-label="Systems">
          {graph.systems.map((s) => (
            <li key={s.href}>
              <a
                href={s.href}
                ref={(el) => {
                  sysEls.current[s.href] = el;
                }}
                className={`lrn-proof-sys${litSys(s.href) ? " on" : ""}`}
                onMouseEnter={() => setHover({ kind: "sys", id: s.href })}
                onFocus={() => setHover({ kind: "sys", id: s.href })}
                onBlur={() => setHover(null)}
                onClick={(e) => {
                  e.preventDefault();
                  onOpenSystem(s.href);
                }}
              >
                <span className="lrn-proof-sys-name">
                  {s.name}
                  {s.href === "/jarvis" && (
                    <span className="lrn-proof-live">live</span>
                  )}
                </span>
                <span className="lrn-proof-sys-n">
                  built on {s.stages.length} stage
                  {s.stages.length === 1 ? "" : "s"}
                </span>
                {/* Narrow screens drop the curves, so the links are
                    restated as the stages under each system. */}
                <span className="lrn-proof-sys-from">
                  {s.stages
                    .map((id) => graph.stages.find((x) => x.id === id))
                    .filter(Boolean)
                    .map((x) => (
                      <span key={x.id} style={{ "--c": x.accent }}>
                        {x.title}
                      </span>
                    ))}
                </span>
                <em aria-hidden="true">→</em>
              </a>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}
