import React, { useState } from "react";

/* 0.6 — Context. Everything competes for the same room, and the thing that
   gets evicted is almost never the thing you'd choose. Pure arithmetic. */

const WINDOW = 128000;

const PARTS = [
  {
    key: "system",
    label: "System prompt",
    color: "#7C9EB2",
    min: 200,
    max: 8000,
  },
  { key: "tools", label: "Tool schemas", color: "#B08BB4", min: 0, max: 30000 },
  {
    key: "history",
    label: "Conversation history",
    color: "#8BB4A0",
    min: 0,
    max: 90000,
  },
  {
    key: "retrieved",
    label: "Retrieved chunks",
    color: "#C9A05D",
    min: 0,
    max: 90000,
  },
];

const fmt = (n) => (n >= 1000 ? `${Math.round(n / 1000)}k` : String(n));

export default function ContextBudget() {
  const [v, setV] = useState({
    system: 1200,
    tools: 6000,
    history: 24000,
    retrieved: 18000,
  });

  const used = PARTS.reduce((s, p) => s + v[p.key], 0);
  const over = used > WINDOW;
  const free = Math.max(WINDOW - used, 0);
  const pct = (n) => (n / WINDOW) * 100;

  return (
    <div className="viz">
      <div
        className={`ctx-bar ${over ? "over" : ""}`}
        role="img"
        aria-label="Context window usage"
      >
        {PARTS.map((p) => (
          <div
            key={p.key}
            className="ctx-seg"
            style={{
              width: `${Math.min(pct(v[p.key]), 100)}%`,
              background: p.color,
            }}
            title={`${p.label}: ${fmt(v[p.key])}`}
          />
        ))}
        {!over && (
          <div className="ctx-free" style={{ width: `${pct(free)}%` }} />
        )}
      </div>

      <div className="ctx-legend">
        {PARTS.map((p) => (
          <div key={p.key} className="ctx-ctl">
            <label className="viz-label" htmlFor={`ctx-${p.key}`}>
              <i style={{ background: p.color }} /> {p.label}{" "}
              <strong>{fmt(v[p.key])}</strong>
            </label>
            <input
              id={`ctx-${p.key}`}
              className="viz-range"
              type="range"
              min={p.min}
              max={p.max}
              step="200"
              value={v[p.key]}
              onChange={(e) => setV({ ...v, [p.key]: Number(e.target.value) })}
            />
          </div>
        ))}
      </div>

      <p className="viz-note" aria-live="polite">
        {over ? (
          <>
            <strong>{fmt(used - WINDOW)} over.</strong> Something has to go, and
            in most frameworks the default is the oldest history — which is
            usually where the user told you what they actually wanted. Evicting
            well is a design decision, not a library default.
          </>
        ) : (
          <>
            {fmt(used)} of {fmt(WINDOW)} used, {fmt(free)} free. Every one of
            those tokens is paid for on every single turn — an agent with 30k of
            tool schemas pays that on turn one and turn fifty.
          </>
        )}
      </p>
      <p className="viz-caveat">
        Real arithmetic against a 128k window. Model limits and per-token prices
        vary; the competition for space does not.
      </p>
    </div>
  );
}
